import {catalog,commercialTerms,brl,checkoutFor} from './catalog.js';
import {arrowIcon} from './site-interactions.js';
import {whatsappLink} from './content.js';
const contact=(service,plan='')=>`${whatsappLink}?text=${encodeURIComponent(`Olá, Genesis! Tenho interesse em ${service.name}${plan?' — plano '+plan:''}. ${service.availability==='development'?'Gostaria de saber quando estará disponível.':'Gostaria de confirmar o escopo e os valores.'}`)}`;
const external='target="_blank" rel="noopener noreferrer"';
const tag=text=>`<p class="eyebrow"><span></span>${text}</p>`;
const card=(s,index)=>`<article class="glass project-card catalog-card reveal" data-category="${s.category}">
 <button class="catalog-preview" type="button" data-preview-solution="${s.id}" aria-label="Conhecer a solução: ${s.name}">
  <span class="catalog-window" aria-hidden="true"><span class="catalog-window-dots"><i></i><i></i><i></i></span><span>${s.brand}</span><span class="catalog-window-open">${arrowIcon()}</span></span>
  <img src="/solutions/${s.image}.jpg" alt="${s.availability==='development'?`Apresentação do projeto ${s.brand}, em desenvolvimento`:s.id==='stock'?'Tela pública de login do Armazém In':`Captura da demonstração ${s.brand}`}" width="1440" height="960" loading="lazy">
  <span class="catalog-image-tag">${s.status}</span>
 </button>
 <div class="project-copy"><div class="catalog-card-meta"><span class="category">${s.category}</span><span class="catalog-project-number">0${index+1}</span></div><h3>${s.name}</h3>
 <div class="catalog-card-actions"><button class="catalog-plan-button" data-solution="${s.id}" aria-label="Comparar planos: ${s.name}">Conhecer solução <span>${arrowIcon()}</span></button><a class="text-link catalog-demo" href="${s.demoUrl||contact(s)}" ${external}>${s.availability==='development'?'Acompanhar lançamento':s.demoUrl?'Ver projeto':'Solicitar demonstração'}<span aria-hidden="true">${arrowIcon()}</span></a></div></div></article>`;
export function renderCatalog(){
 return `<section class="scene scene-solutions catalog-scene"><div class="catalog-heading reveal"><div>${tag('01 / PROJETOS & SOLUÇÕES')}<h2>Ideias que você<br><em>já pode explorar.</em></h2></div><p class="lead">Conheça os projetos.<br> Encontre a solução para o seu negócio.</p></div>
 <div class="catalog-tools reveal"><div class="filters" aria-label="Filtrar soluções">${['Todos',...new Set(catalog.map(s=>s.category))].map((c,i)=>`<button data-filter="${c}" aria-pressed="${i===0}">${c}</button>`).join('')}</div><div class="rail-controls"><button data-rail="-1" aria-label="Soluções anteriores">${arrowIcon('left')}</button><button data-rail="1" aria-label="Mais soluções">${arrowIcon('right')}</button></div></div>
 <div class="projects-rail catalog-rail scene-scroll" tabindex="0" aria-label="Galeria de projetos e soluções">${catalog.map(card).join('')}</div>
 <div class="catalog-bottom reveal"><p class="catalog-review"><span class="catalog-review-dot"></span>Projetos demonstrativos · implantação + mensalidade · contratação por proposta.</p><span id="result-count" role="status">${catalog.length} soluções</span></div></section>`;
}
export function renderSolution(service){
 const development=service.availability==='development';
 return `<div class="solution-intro"><span class="category">${service.category} / ${service.brand}</span><h2 id="project-title">${service.name}</h2><p>${service.description}</p>${development?`<div class="solution-availability"><strong>Em desenvolvimento</strong><span>Este serviço ainda não está disponível para contratação. Conheça a proposta e acompanhe o lançamento.</span></div>`:''}<div class="solution-demo"><a class="primary solution-demo-cta" href="${service.demoUrl||contact(service)}" ${external}>${service.demoLabel}<span aria-hidden="true">${arrowIcon()}</span></a><small>${development?'Interesse no lançamento · abre o WhatsApp':service.demoUrl?'Explore o projeto · abre em nova aba':'Apresentação guiada pelo WhatsApp'}</small></div></div>
 <div class="solution-facts"><ul>${service.features.map(f=>`<li>${f}</li>`).join('')}</ul></div>
 <div class="plan-heading"><div><span class="category">O PRÓXIMO PASSO</span><h3>${development?'Planos previstos para o lançamento.':'Um plano para cada momento.'}</h3></div><p>${development?'Valores e franquias planejados, sujeitos à confirmação no lançamento. Nenhuma assinatura está sendo vendida para este serviço.':'Implantação única para configurar a solução. Mensalidade de hospedagem, manutenção e suporte a partir da entrega, dentro do escopo contratado.'}</p></div>
 <div class="solution-plans" style="--plan-count:${service.plans.length}">${service.plans.map((p,i)=>`<article class="solution-plan ${i===1?'plan-featured':''}"><span class="plan-label">${p.name}</span><div class="plan-price">${brl(p.monthly)}<small>/mês</small></div><p class="plan-setup">Implantação única: ${brl(p.setup)}</p><ul>${p.features.map(f=>`<li>${f}</li>`).join('')}</ul><div class="plan-limits"><h4>${development?'Franquias previstas':'Limites incluídos'}</h4><ul>${p.limits.map(f=>`<li>${f}</li>`).join('')}</ul></div>${!development&&checkoutFor(p)?`<a class="primary plan-cta" href="${checkoutFor(p)}" ${external}>Contratar na Kiwify <span>${arrowIcon()}</span></a>`:`<a class="primary plan-cta" href="${contact(service,p.name)}" ${external}>${development?'Tenho interesse no lançamento':'Conversar sobre o plano'} <span>${arrowIcon()}</span></a>`}</article>`).join('')}</div>
 ${service.optionalAI?`<div class="solution-addon"><div><span class="category">UMA POSSIBILIDADE A MAIS</span><h3>Atendimento com IA, em desenvolvimento.</h3><p>Estamos preparando uma solução para responder dúvidas e organizar contatos. Ainda não está disponível e não está incluída nos planos acima.</p></div><a class="text-link" href="${contact(catalog.find(s=>s.id==='assistant'))}" ${external}>Acompanhar lançamento <span aria-hidden="true">${arrowIcon()}</span></a></div>`:''}
 <div class="solution-scope"><h3>Antes de começar</h3><p>${service.scope}</p><details class="solution-terms"><summary>O que está incluído e como funciona o suporte</summary><div>${['included','support','excluded','changes'].map(key=>`<p>${commercialTerms[key]}</p>`).join('')}</div></details><p>A contratação acontece por proposta, após confirmar escopo e disponibilidade. Este site não realiza pagamentos nem ativa contas automaticamente.</p></div>`;
}
